<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import * as backupAPI from '@shared-api/admin/backup'
import * as dataAPI from '@shared-api/admin/dataManagement'
import type { BackupDownloadPart, BackupRecord, BackupS3Config, BackupScheduleConfig, ImageStorageConfig } from '@shared-api/admin/backup'
import type { BackupAgentHealth, BackupJob, BackupJobStatus, BackupType as DataBackupType, DataManagementConfig, DataManagementS3Profile, DataManagementSourceConfig, DataManagementSourceProfile, SourceType } from '@shared-api/admin/dataManagement'
import ConsoleShell from '@/components/layout/ConsoleShell.vue'
import PageState from '@/components/base/PageState.vue'
import SurfaceDialog from '@/components/base/SurfaceDialog.vue'
import { DialogWidth } from '@/components/base/dialog'
import { ConfirmTone, useConfirmStore } from '@/stores/confirm'
import { useAppStore } from '@/stores/app'
import { BackupType, BackupWorkspaceTab, DataSourceType, cloneData, formatGovernanceDate } from '@/features/admin/governance/model'

const app = useAppStore()
const confirm = useConfirmStore()
const { t } = useI18n()
const activeTab = ref(BackupWorkspaceTab.STORAGE)
const loading = ref(true)
const error = ref('')
const working = ref(false)
const s3 = ref<BackupS3Config>({ endpoint: '', region: '', bucket: '', access_key_id: '', secret_access_key: '', prefix: 'backups/', force_path_style: false })
const s3SecretConfigured = ref(false)
const imageStorage = ref<ImageStorageConfig>({ enabled: false, reuse_backup_s3: true, bucket: '', prefix: 'images/', public_base_url: '', presign_expiry_hours: 24, max_download_bytes: 104857600, endpoint: '', region: '', access_key_id: '', secret_access_key: '', force_path_style: false })
const imageSecretConfigured = ref(false)
const schedule = ref<BackupScheduleConfig>({ enabled: false, cron_expr: '0 2 * * *', retain_days: 30, retain_count: 10 })
const backups = ref<BackupRecord[]>([])
const manualExpireDays = ref(14)
const restoreOpen = ref(false)
const restoring = ref<BackupRecord | null>(null)
const restorePassword = ref('')
const downloadPartsOpen = ref(false)
const downloadParts = ref<BackupDownloadPart[]>([])
const r2GuideOpen = ref(false)
const agentHealth = ref<BackupAgentHealth | null>(null)
const dataConfig = ref<DataManagementConfig | null>(null)
const postgresProfiles = ref<DataManagementSourceProfile[]>([])
const redisProfiles = ref<DataManagementSourceProfile[]>([])
const s3Profiles = ref<DataManagementS3Profile[]>([])
const jobs = ref<BackupJob[]>([])
const jobStatus = ref('')
const jobType = ref('')
const jobDetail = ref<BackupJob | null>(null)
const jobDetailOpen = ref(false)
const createJobOpen = ref(false)
const jobForm = reactive({ backupType: BackupType.FULL, uploadToS3: true, s3ProfileId: '', postgresProfileId: '', redisProfileId: '' })
const profileOpen = ref(false)
const profileKind = ref<DataSourceType | 's3'>(DataSourceType.POSTGRES)
const editingProfileId = ref('')
const profileForm = reactive({ profileId: '', name: '', setActive: false, enabled: true, endpoint: '', region: '', bucket: '', accessKeyId: '', secretAccessKey: '', prefix: '', forcePathStyle: false, useSSL: true, host: '', port: 5432, user: '', password: '', database: '', sslMode: 'disable', addr: '127.0.0.1:6379', username: '', db: 0, containerName: '' })
let pollTimer: number | null = null

const completedBackups = computed(() => backups.value.filter((item) => item.status === 'completed').length)
const runningBackups = computed(() => backups.value.filter((item) => item.status === 'running' || item.status === 'pending').length)
const r2ConfigRows = computed(() => [
  { field: t('admin.backup.s3.endpoint'), value: 'https://<account_id>.r2.cloudflarestorage.com' },
  { field: t('admin.backup.s3.region'), value: 'auto' },
  { field: t('admin.backup.s3.bucket'), value: t('admin.backup.r2Guide.step4.bucketValue') },
  { field: t('admin.backup.s3.prefix'), value: 'backups/' },
  { field: 'Access Key ID', value: t('admin.backup.r2Guide.step4.fromStep2') },
  { field: 'Secret Access Key', value: t('admin.backup.r2Guide.step4.fromStep2') },
  { field: t('admin.backup.s3.forcePathStyle'), value: t('admin.backup.r2Guide.step4.unchecked') }
])

async function loadClassic(): Promise<void> {
  const results = await Promise.allSettled([backupAPI.getS3Config(), backupAPI.getImageStorageConfig(), backupAPI.getSchedule(), backupAPI.listBackups()])
  if (results[0].status === 'fulfilled') { s3.value = { ...results[0].value, secret_access_key: '' }; s3SecretConfigured.value = true }
  if (results[1].status === 'fulfilled') { imageStorage.value = { ...results[1].value.config, secret_access_key: '' }; imageSecretConfigured.value = results[1].value.secret_configured }
  if (results[2].status === 'fulfilled') schedule.value = results[2].value
  if (results[3].status === 'fulfilled') backups.value = results[3].value.items || []
}

async function loadDataManagement(): Promise<void> {
  const results = await Promise.allSettled([dataAPI.getAgentHealth(), dataAPI.getConfig(), dataAPI.listSourceProfiles(DataSourceType.POSTGRES), dataAPI.listSourceProfiles(DataSourceType.REDIS), dataAPI.listS3Profiles(), dataAPI.listBackupJobs({ page_size: 100, status: jobStatus.value ? jobStatus.value as BackupJobStatus : undefined, backup_type: jobType.value ? jobType.value as DataBackupType : undefined })])
  if (results[0].status === 'fulfilled') agentHealth.value = results[0].value
  if (results[1].status === 'fulfilled') dataConfig.value = results[1].value
  if (results[2].status === 'fulfilled') postgresProfiles.value = results[2].value.items || []
  if (results[3].status === 'fulfilled') redisProfiles.value = results[3].value.items || []
  if (results[4].status === 'fulfilled') s3Profiles.value = results[4].value.items || []
  if (results[5].status === 'fulfilled') jobs.value = results[5].value.items || []
}

async function loadAll(): Promise<void> { loading.value = true; error.value = ''; try { await Promise.all([loadClassic(), loadDataManagement()]) } catch (caught) { error.value = (caught as { message?: string }).message || '数据管理加载失败' } finally { loading.value = false } }
async function saveS3(): Promise<void> { working.value = true; try { s3.value = { ...(await backupAPI.updateS3Config(cloneData(s3.value))), secret_access_key: '' }; s3SecretConfigured.value = true; app.showSuccess('备份 S3 配置已保存') } catch (caught) { app.showError((caught as { message?: string }).message || 'S3 配置保存失败') } finally { working.value = false } }
async function testS3(): Promise<void> { working.value = true; try { const result = await backupAPI.testS3Connection(cloneData(s3.value)); result.ok ? app.showSuccess(result.message) : app.showError(result.message) } catch (caught) { app.showError((caught as { message?: string }).message || 'S3 测试失败') } finally { working.value = false } }
async function saveImageStorage(): Promise<void> { working.value = true; try { imageStorage.value = { ...(await backupAPI.updateImageStorageConfig(cloneData(imageStorage.value))), secret_access_key: '' }; imageSecretConfigured.value = true; app.showSuccess('图片存储配置已保存') } catch (caught) { app.showError((caught as { message?: string }).message || '图片存储保存失败') } finally { working.value = false } }
async function testImageStorage(): Promise<void> { working.value = true; try { const result = await backupAPI.testImageStorageConnection(cloneData(imageStorage.value)); result.ok ? app.showSuccess(result.message) : app.showError(result.message) } catch (caught) { app.showError((caught as { message?: string }).message || '图片存储测试失败') } finally { working.value = false } }
async function saveSchedule(): Promise<void> { working.value = true; try { schedule.value = await backupAPI.updateSchedule(cloneData(schedule.value)); app.showSuccess('备份计划已保存') } catch (caught) { app.showError((caught as { message?: string }).message || '计划保存失败') } finally { working.value = false } }
async function createBackup(): Promise<void> { working.value = true; try { const result = await backupAPI.createBackup({ expire_days: manualExpireDays.value || undefined }); backups.value.unshift(result); app.showSuccess('备份任务已创建'); startPolling() } catch (caught) { app.showError((caught as { message?: string }).message || '备份创建失败') } finally { working.value = false } }
async function removeBackup(item: BackupRecord): Promise<void> { if (!await confirm.ask({ title: '删除备份', message: `确认删除 ${item.file_name || item.id}？S3 对象也会被删除。`, confirmText: '删除备份', tone: ConfirmTone.DANGER })) return; try { await backupAPI.deleteBackup(item.id); app.showSuccess('备份已删除'); await loadClassic() } catch (caught) { app.showError((caught as { message?: string }).message || '备份删除失败') } }
async function downloadBackup(item: BackupRecord): Promise<void> { try { const result = await backupAPI.getDownloadURL(item.id); if (result.url) window.open(result.url, '_blank', 'noopener,noreferrer'); else { downloadParts.value = result.parts || []; downloadPartsOpen.value = true } } catch (caught) { app.showError((caught as { message?: string }).message || '下载链接获取失败') } }
function openRestore(item: BackupRecord): void { restoring.value = item; restorePassword.value = ''; restoreOpen.value = true }
async function restoreBackup(): Promise<void> { if (!restoring.value || !restorePassword.value) { app.showError('请输入数据库管理员密码'); return } if (!await confirm.ask({ title: '恢复备份', message: '恢复会覆盖当前数据库与缓存数据，服务期间可能不可用。', confirmText: '确认恢复', tone: ConfirmTone.DANGER })) return; working.value = true; try { const result = await backupAPI.restoreBackup(restoring.value.id, restorePassword.value); const index = backups.value.findIndex((item) => item.id === result.id); if (index >= 0) backups.value[index] = result; restoreOpen.value = false; app.showSuccess('恢复任务已启动'); startPolling() } catch (caught) { app.showError((caught as { message?: string }).message || '恢复启动失败') } finally { working.value = false } }

async function saveDataConfig(): Promise<void> { if (!dataConfig.value) return; working.value = true; try { dataConfig.value = await dataAPI.updateConfig(cloneData(dataConfig.value)); app.showSuccess('备份 Agent 配置已保存') } catch (caught) { app.showError((caught as { message?: string }).message || 'Agent 配置保存失败') } finally { working.value = false } }
function resetProfileForm(kind: DataSourceType | 's3'): void { profileKind.value = kind; editingProfileId.value = ''; Object.assign(profileForm, { profileId: '', name: '', setActive: false, enabled: true, endpoint: '', region: '', bucket: '', accessKeyId: '', secretAccessKey: '', prefix: '', forcePathStyle: false, useSSL: true, host: '', port: kind === DataSourceType.REDIS ? 6379 : 5432, user: '', password: '', database: '', sslMode: 'disable', addr: '127.0.0.1:6379', username: '', db: 0, containerName: '' }) }
function openCreateProfile(kind: DataSourceType | 's3'): void { resetProfileForm(kind); profileOpen.value = true }
function sourceToForm(item: DataManagementSourceProfile): void { resetProfileForm(item.source_type as DataSourceType); editingProfileId.value = item.profile_id; const value = item.config; Object.assign(profileForm, { profileId: item.profile_id, name: item.name, host: value.host || '', port: value.port || (item.source_type === DataSourceType.POSTGRES ? 5432 : 6379), user: value.user || '', database: value.database || '', sslMode: value.ssl_mode || 'disable', addr: value.addr || '', username: value.username || '', db: value.db || 0, containerName: value.container_name || '' }); profileOpen.value = true }
function s3ToForm(item: DataManagementS3Profile): void { resetProfileForm('s3'); editingProfileId.value = item.profile_id; Object.assign(profileForm, { profileId: item.profile_id, name: item.name, enabled: item.s3.enabled, endpoint: item.s3.endpoint, region: item.s3.region, bucket: item.s3.bucket, accessKeyId: item.s3.access_key_id, prefix: item.s3.prefix, forcePathStyle: item.s3.force_path_style, useSSL: item.s3.use_ssl }); profileOpen.value = true }
function sourceConfig(): DataManagementSourceConfig { return { host: profileForm.host, port: Number(profileForm.port), user: profileForm.user, password: profileForm.password || undefined, database: profileForm.database, ssl_mode: profileForm.sslMode, addr: profileForm.addr, username: profileForm.username, db: Number(profileForm.db), container_name: profileForm.containerName } }
async function saveProfile(): Promise<void> { if (!profileForm.profileId.trim() || !profileForm.name.trim()) { app.showError('Profile ID 和名称不能为空'); return } working.value = true; try { if (profileKind.value === 's3') { const payload = { name: profileForm.name, enabled: profileForm.enabled, endpoint: profileForm.endpoint, region: profileForm.region, bucket: profileForm.bucket, access_key_id: profileForm.accessKeyId, secret_access_key: profileForm.secretAccessKey || undefined, prefix: profileForm.prefix, force_path_style: profileForm.forcePathStyle, use_ssl: profileForm.useSSL }; if (editingProfileId.value) await dataAPI.updateS3Profile(editingProfileId.value, payload); else await dataAPI.createS3Profile({ profile_id: profileForm.profileId, set_active: profileForm.setActive, ...payload }) } else { const payload = { name: profileForm.name, config: sourceConfig() }; if (editingProfileId.value) await dataAPI.updateSourceProfile(profileKind.value as SourceType, editingProfileId.value, payload); else await dataAPI.createSourceProfile(profileKind.value as SourceType, { profile_id: profileForm.profileId, set_active: profileForm.setActive, ...payload }) } profileOpen.value = false; app.showSuccess('数据源配置已保存'); await loadDataManagement() } catch (caught) { app.showError((caught as { message?: string }).message || 'Profile 保存失败') } finally { working.value = false } }
async function activateSource(item: DataManagementSourceProfile): Promise<void> { try { await dataAPI.setActiveSourceProfile(item.source_type, item.profile_id); app.showSuccess('数据源已设为活动'); await loadDataManagement() } catch (caught) { app.showError((caught as { message?: string }).message || '激活失败') } }
async function activateS3(item: DataManagementS3Profile): Promise<void> { try { await dataAPI.setActiveS3Profile(item.profile_id); app.showSuccess('S3 Profile 已激活'); await loadDataManagement() } catch (caught) { app.showError((caught as { message?: string }).message || '激活失败') } }
async function deleteSource(item: DataManagementSourceProfile): Promise<void> { if (!await confirm.ask({ title: '删除数据源 Profile', message: `确认删除 ${item.name}？活动 Profile 可能无法删除。`, confirmText: '删除', tone: ConfirmTone.DANGER })) return; try { await dataAPI.deleteSourceProfile(item.source_type, item.profile_id); app.showSuccess('数据源已删除'); await loadDataManagement() } catch (caught) { app.showError((caught as { message?: string }).message || '删除失败') } }
async function deleteS3(item: DataManagementS3Profile): Promise<void> { if (!await confirm.ask({ title: '删除 S3 Profile', message: `确认删除 ${item.name}？已上传的备份对象不会自动删除。`, confirmText: '删除', tone: ConfirmTone.DANGER })) return; try { await dataAPI.deleteS3Profile(item.profile_id); app.showSuccess('S3 Profile 已删除'); await loadDataManagement() } catch (caught) { app.showError((caught as { message?: string }).message || '删除失败') } }
async function testProfileS3(): Promise<void> { working.value = true; try { const result = await dataAPI.testS3({ endpoint: profileForm.endpoint, region: profileForm.region, bucket: profileForm.bucket, access_key_id: profileForm.accessKeyId, secret_access_key: profileForm.secretAccessKey, prefix: profileForm.prefix, force_path_style: profileForm.forcePathStyle, use_ssl: profileForm.useSSL }); result.ok ? app.showSuccess(result.message) : app.showError(result.message) } catch (caught) { app.showError((caught as { message?: string }).message || 'S3 测试失败') } finally { working.value = false } }
async function createJob(): Promise<void> { working.value = true; try { const result = await dataAPI.createBackupJob({ backup_type: jobForm.backupType, upload_to_s3: jobForm.uploadToS3, s3_profile_id: jobForm.s3ProfileId || undefined, postgres_profile_id: jobForm.postgresProfileId || undefined, redis_profile_id: jobForm.redisProfileId || undefined, idempotency_key: crypto.randomUUID() }); createJobOpen.value = false; app.showSuccess(`备份任务 ${result.job_id} 已创建`); await loadDataManagement(); startPolling() } catch (caught) { app.showError((caught as { message?: string }).message || '备份任务创建失败') } finally { working.value = false } }
async function openJob(item: BackupJob): Promise<void> { jobDetailOpen.value = true; try { jobDetail.value = await dataAPI.getBackupJob(item.job_id) } catch { jobDetail.value = item } }
function startPolling(): void { if (pollTimer) return; pollTimer = window.setInterval(async () => { const classicRunning = backups.value.some((item) => ['pending', 'running'].includes(item.status) || item.restore_status === 'running'); const agentRunning = jobs.value.some((item) => ['queued', 'running'].includes(item.status)); if (!classicRunning && !agentRunning) { if (pollTimer) window.clearInterval(pollTimer); pollTimer = null; return } await Promise.allSettled([loadClassic(), loadDataManagement()]) }, 5000) }
function switchTab(tab: BackupWorkspaceTab): void { activeTab.value = tab; if ([BackupWorkspaceTab.SOURCES, BackupWorkspaceTab.JOBS].includes(tab)) void loadDataManagement(); if (tab === BackupWorkspaceTab.CLASSIC) void loadClassic() }

onMounted(async () => { await loadAll(); if (runningBackups.value || jobs.value.some((item) => ['queued', 'running'].includes(item.status))) startPolling() })
onBeforeUnmount(() => { if (pollTimer) window.clearInterval(pollTimer) })
</script>

<template>
  <ConsoleShell>
    <main class="resource-page">
      <header class="resource-page__heading"><div><span class="resource-eyebrow">Data Resilience</span><h1>数据与备份</h1><p>对象存储、图片资产、经典备份恢复、Agent 数据源 Profiles 与备份任务统一管理。</p></div><button class="resource-button resource-button--secondary" :disabled="loading" @click="loadAll">刷新全部</button></header>
      <nav class="resource-tabs"><button :aria-selected="activeTab === BackupWorkspaceTab.STORAGE" @click="switchTab(BackupWorkspaceTab.STORAGE)">存储配置</button><button :aria-selected="activeTab === BackupWorkspaceTab.CLASSIC" @click="switchTab(BackupWorkspaceTab.CLASSIC)">备份与恢复</button><button :aria-selected="activeTab === BackupWorkspaceTab.SOURCES" @click="switchTab(BackupWorkspaceTab.SOURCES)">Agent 与数据源</button><button :aria-selected="activeTab === BackupWorkspaceTab.JOBS" @click="switchTab(BackupWorkspaceTab.JOBS)">备份任务</button></nav>
      <PageState :loading="loading" :error="error" @retry="loadAll"><template v-if="activeTab === BackupWorkspaceTab.STORAGE"><section class="governance-grid"><article class="governance-card"><header class="governance-card__header"><div><h2>备份 S3 / R2</h2><p>兼容 AWS S3、<button type="button" class="data-inline-guide" @click="r2GuideOpen = true">Cloudflare R2 配置教程</button>与路径风格对象存储。</p></div><span class="resource-status">{{ s3SecretConfigured ? '密钥已配置' : '未配置密钥' }}</span></header><div class="resource-form-grid"><label>Endpoint<input v-model="s3.endpoint" /></label><label>Region<input v-model="s3.region" /></label><label>Bucket<input v-model="s3.bucket" /></label><label>Prefix<input v-model="s3.prefix" /></label><label>Access Key ID<input v-model="s3.access_key_id" /></label><label>Secret Access Key<input v-model="s3.secret_access_key" type="password" :placeholder="s3SecretConfigured ? '留空保留' : ''" /></label><label class="resource-check"><input v-model="s3.force_path_style" type="checkbox" />Force path style</label></div><div class="resource-inline-actions"><button class="resource-button resource-button--secondary" :disabled="working" @click="testS3">测试连接</button><button class="resource-button" :disabled="working" @click="saveS3">保存 S3</button></div></article><article class="governance-card"><header class="governance-card__header"><div><h2>异步图片对象存储</h2><p>可复用备份 S3 凭据，或使用独立 Endpoint 与密钥。</p></div><span class="resource-status">{{ imageSecretConfigured ? '密钥已配置' : '未配置密钥' }}</span></header><div class="resource-form-grid"><label class="resource-check"><input v-model="imageStorage.enabled" type="checkbox" />启用图片存储</label><label class="resource-check"><input v-model="imageStorage.reuse_backup_s3" type="checkbox" />复用备份 S3</label><label>Bucket<input v-model="imageStorage.bucket" /></label><label>Prefix<input v-model="imageStorage.prefix" /></label><label>公开基础 URL<input v-model="imageStorage.public_base_url" /></label><label>签名有效小时<input v-model.number="imageStorage.presign_expiry_hours" type="number" min="1" /></label><label>最大下载字节<input v-model.number="imageStorage.max_download_bytes" type="number" min="1" /></label><template v-if="!imageStorage.reuse_backup_s3"><label>Endpoint<input v-model="imageStorage.endpoint" /></label><label>Region<input v-model="imageStorage.region" /></label><label>Access Key ID<input v-model="imageStorage.access_key_id" /></label><label>Secret Access Key<input v-model="imageStorage.secret_access_key" type="password" :placeholder="imageSecretConfigured ? '留空保留' : ''" /></label><label class="resource-check"><input v-model="imageStorage.force_path_style" type="checkbox" />Force path style</label></template></div><div class="resource-inline-actions"><button class="resource-button resource-button--secondary" :disabled="working" @click="testImageStorage">测试连接</button><button class="resource-button" :disabled="working" @click="saveImageStorage">保存图片存储</button></div></article></section></template>
        <template v-else-if="activeTab === BackupWorkspaceTab.CLASSIC"><section class="resource-summary"><div><span>备份总数</span><strong>{{ backups.length }}</strong></div><div><span>已完成</span><strong>{{ completedBackups }}</strong></div><div><span>进行中</span><strong>{{ runningBackups }}</strong></div><div><span>失败</span><strong>{{ backups.filter((item) => item.status === 'failed').length }}</strong></div></section><section class="governance-card"><header class="governance-card__header"><div><h2>自动备份计划</h2><p>Cron、保留天数与最多保留份数。</p></div><button class="resource-button" :disabled="working" @click="saveSchedule">保存计划</button></header><div class="resource-form-grid resource-form-grid--4"><label class="resource-check"><input v-model="schedule.enabled" type="checkbox" />启用计划</label><label>Cron<input v-model="schedule.cron_expr" /></label><label>保留天数<input v-model.number="schedule.retain_days" type="number" min="0" /></label><label>保留份数<input v-model.number="schedule.retain_count" type="number" min="0" /></label></div></section><div class="resource-toolbar"><div class="resource-toolbar__filters"><label>手动备份有效天数<input v-model.number="manualExpireDays" type="number" min="0" /></label></div><button class="resource-button" :disabled="working" @click="createBackup">立即创建备份</button></div><div class="resource-table"><table><thead><tr><th>备份</th><th>状态</th><th>大小</th><th>触发</th><th>时间</th><th>恢复</th><th>操作</th></tr></thead><tbody><tr v-for="item in backups" :key="item.id"><td>{{ item.file_name || item.id }}<small>{{ item.backup_type }} · {{ item.s3_key }}</small></td><td><span :class="['resource-status', item.status === 'completed' ? 'resource-status--active' : item.status === 'failed' ? 'resource-status--error' : '']">{{ item.status }}</span><small>{{ item.progress || item.error_message }}</small></td><td>{{ (item.size_bytes / 1024 / 1024).toFixed(2) }} MB<small v-if="item.parts?.length">{{ item.parts.length }} 分片</small></td><td>{{ item.triggered_by }}</td><td>{{ formatGovernanceDate(item.started_at) }}<small>{{ item.finished_at ? `完成 ${formatGovernanceDate(item.finished_at)}` : '' }}</small></td><td>{{ item.restore_status || '—' }}<small>{{ item.restore_error || (item.restored_at ? formatGovernanceDate(item.restored_at) : '') }}</small></td><td><div class="resource-inline-actions"><button v-if="item.status === 'completed'" class="resource-link" @click="downloadBackup(item)">下载</button><button v-if="item.status === 'completed'" class="resource-link" @click="openRestore(item)">恢复</button><button class="resource-link resource-link--danger" @click="removeBackup(item)">删除</button></div></td></tr></tbody></table></div></template>
        <template v-else-if="activeTab === BackupWorkspaceTab.SOURCES"><section v-if="agentHealth" class="resource-summary"><div><span>Agent</span><strong>{{ agentHealth.enabled ? '已启用' : '未启用' }}</strong></div><div><span>状态 / 版本</span><strong>{{ agentHealth.agent?.status || agentHealth.reason || '—' }} / {{ agentHealth.agent?.version || '—' }}</strong></div><div><span>Socket</span><strong>{{ agentHealth.socket_path || '—' }}</strong></div><div><span>运行秒数</span><strong>{{ agentHealth.agent?.uptime_seconds || 0 }}</strong></div></section><article v-if="dataConfig" class="governance-card"><header class="governance-card__header"><div><h2>Agent 全局配置</h2><p>活动 Profiles 会同步显示；密码留空保留。</p></div><button class="resource-button" :disabled="working" @click="saveDataConfig">保存 Agent 配置</button></header><div class="resource-form-grid resource-form-grid--4"><label>来源模式<select v-model="dataConfig.source_mode"><option value="direct">direct</option><option value="docker_exec">docker_exec</option></select></label><label>备份根目录<input v-model="dataConfig.backup_root" /></label><label>SQLite 路径<input v-model="dataConfig.sqlite_path" /></label><label>保留天数<input v-model.number="dataConfig.retention_days" type="number" /></label><label>至少保留份数<input v-model.number="dataConfig.keep_last" type="number" /></label></div></article><section class="governance-grid governance-grid--3"><article class="governance-card"><header class="governance-card__header"><div><h2>Postgres Profiles</h2></div><button class="resource-button" @click="openCreateProfile(DataSourceType.POSTGRES)">新增</button></header><div class="governance-list"><article v-for="item in postgresProfiles" :key="item.profile_id"><div><strong>{{ item.name }}</strong><small>{{ item.profile_id }} · {{ item.config.host }}:{{ item.config.port }}/{{ item.config.database }}</small></div><div class="resource-inline-actions"><span v-if="item.is_active" class="resource-status resource-status--active">活动</span><button v-else class="resource-link" @click="activateSource(item)">激活</button><button class="resource-link" @click="sourceToForm(item)">编辑</button><button class="resource-link resource-link--danger" @click="deleteSource(item)">删除</button></div></article></div></article><article class="governance-card"><header class="governance-card__header"><div><h2>Redis Profiles</h2></div><button class="resource-button" @click="openCreateProfile(DataSourceType.REDIS)">新增</button></header><div class="governance-list"><article v-for="item in redisProfiles" :key="item.profile_id"><div><strong>{{ item.name }}</strong><small>{{ item.profile_id }} · {{ item.config.addr }} / DB {{ item.config.db }}</small></div><div class="resource-inline-actions"><span v-if="item.is_active" class="resource-status resource-status--active">活动</span><button v-else class="resource-link" @click="activateSource(item)">激活</button><button class="resource-link" @click="sourceToForm(item)">编辑</button><button class="resource-link resource-link--danger" @click="deleteSource(item)">删除</button></div></article></div></article><article class="governance-card"><header class="governance-card__header"><div><h2>S3 Profiles</h2></div><button class="resource-button" @click="openCreateProfile('s3')">新增</button></header><div class="governance-list"><article v-for="item in s3Profiles" :key="item.profile_id"><div><strong>{{ item.name }}</strong><small>{{ item.profile_id }} · {{ item.s3.bucket }}/{{ item.s3.prefix }}</small></div><div class="resource-inline-actions"><span v-if="item.is_active" class="resource-status resource-status--active">活动</span><button v-else class="resource-link" @click="activateS3(item)">激活</button><button class="resource-link" @click="s3ToForm(item)">编辑</button><button class="resource-link resource-link--danger" @click="deleteS3(item)">删除</button></div></article></div></article></section></template>
        <template v-else><div class="resource-toolbar"><div class="resource-toolbar__filters"><select v-model="jobStatus" @change="loadDataManagement"><option value="">全部状态</option><option value="queued">queued</option><option value="running">running</option><option value="succeeded">succeeded</option><option value="failed">failed</option><option value="partial_succeeded">partial_succeeded</option></select><select v-model="jobType" @change="loadDataManagement"><option value="">全部类型</option><option :value="BackupType.POSTGRES">Postgres</option><option :value="BackupType.REDIS">Redis</option><option :value="BackupType.FULL">完整</option></select></div><button class="resource-button" @click="createJobOpen = true">创建 Agent 备份</button></div><div class="resource-table"><table><thead><tr><th>任务</th><th>类型</th><th>状态</th><th>Profiles</th><th>产物</th><th>时间</th><th>操作</th></tr></thead><tbody><tr v-for="item in jobs" :key="item.job_id"><td><code>{{ item.job_id }}</code><small>{{ item.triggered_by }}</small></td><td>{{ item.backup_type }}</td><td><span :class="['resource-status', item.status === 'succeeded' ? 'resource-status--active' : item.status === 'failed' ? 'resource-status--error' : '']">{{ item.status }}</span><small>{{ item.error_message }}</small></td><td>PG {{ item.postgres_profile_id || '—' }} · Redis {{ item.redis_profile_id || '—' }}<small>S3 {{ item.s3_profile_id || '—' }}</small></td><td>{{ item.artifact ? `${(item.artifact.size_bytes / 1024 / 1024).toFixed(2)} MB` : '—' }}<small>{{ item.s3 ? `${item.s3.bucket}/${item.s3.key}` : '' }}</small></td><td>{{ formatGovernanceDate(item.started_at) }}<small>{{ formatGovernanceDate(item.finished_at) }}</small></td><td><button class="resource-link" @click="openJob(item)">刷新详情</button></td></tr></tbody></table></div></template>
      </PageState>
    </main>

    <SurfaceDialog :show="r2GuideOpen" :title="t('admin.backup.r2Guide.title')" :description="t('admin.backup.r2Guide.intro')" :width="DialogWidth.WIDE" @close="r2GuideOpen = false"><div class="r2-guide"><article><strong><i>1</i>{{ t('admin.backup.r2Guide.step1.title') }}</strong><ol><li>{{ t('admin.backup.r2Guide.step1.line1') }}</li><li>{{ t('admin.backup.r2Guide.step1.line2') }}</li><li>{{ t('admin.backup.r2Guide.step1.line3') }}</li></ol></article><article><strong><i>2</i>{{ t('admin.backup.r2Guide.step2.title') }}</strong><ol><li>{{ t('admin.backup.r2Guide.step2.line1') }}</li><li>{{ t('admin.backup.r2Guide.step2.line2') }}</li><li>{{ t('admin.backup.r2Guide.step2.line3') }}</li><li>{{ t('admin.backup.r2Guide.step2.line4') }}</li></ol><p class="notice notice--error">{{ t('admin.backup.r2Guide.step2.warning') }}</p></article><article><strong><i>3</i>{{ t('admin.backup.r2Guide.step3.title') }}</strong><p>{{ t('admin.backup.r2Guide.step3.desc') }}</p><code>https://&lt;{{ t('admin.backup.r2Guide.step3.accountId') }}&gt;.r2.cloudflarestorage.com</code></article><article><strong><i>4</i>{{ t('admin.backup.r2Guide.step4.title') }}</strong><dl><template v-for="row in r2ConfigRows" :key="row.field"><dt>{{ row.field }}</dt><dd><code>{{ row.value }}</code></dd></template></dl></article><p class="r2-guide__free">{{ t('admin.backup.r2Guide.freeTier') }}</p></div><template #footer><button class="button button--primary" @click="r2GuideOpen = false">{{ t('common.close') }}</button></template></SurfaceDialog>
    <SurfaceDialog :show="restoreOpen" title="恢复备份" description="该操作会覆盖当前数据，恢复过程由后端异步执行并显示在备份列表。" :width="DialogWidth.COMPACT" @close="restoreOpen = false"><form id="backup-restore-form" class="resource-form-stack" @submit.prevent="restoreBackup"><label>数据库管理员密码<input v-model="restorePassword" type="password" required autocomplete="current-password" /></label></form><template #footer><button class="button button--secondary" @click="restoreOpen = false">取消</button><button type="submit" form="backup-restore-form" class="button resource-button--danger" :disabled="working">确认恢复</button></template></SurfaceDialog>
    <SurfaceDialog :show="downloadPartsOpen" title="分片下载" description="多分片备份需逐个下载并按索引保存。" :width="DialogWidth.STANDARD" @close="downloadPartsOpen = false"><div class="governance-list"><article v-for="part in downloadParts" :key="part.index"><div><strong>Part {{ part.index }}</strong><small>{{ (part.size_bytes / 1024 / 1024).toFixed(2) }} MB</small></div><a class="resource-button resource-button--secondary" :href="part.url" target="_blank" rel="noopener noreferrer">下载</a></article></div></SurfaceDialog>
    <SurfaceDialog :show="profileOpen" :title="`${editingProfileId ? '编辑' : '创建'} ${profileKind} Profile`" description="密码或密钥留空时保留已配置值；Profile ID 创建后不可修改。" :width="DialogWidth.WIDE" @close="profileOpen = false"><form id="profile-form" class="resource-form-stack" @submit.prevent="saveProfile"><div class="resource-form-grid"><label>Profile ID *<input v-model="profileForm.profileId" :disabled="Boolean(editingProfileId)" required /></label><label>名称 *<input v-model="profileForm.name" required /></label><label v-if="!editingProfileId" class="resource-check"><input v-model="profileForm.setActive" type="checkbox" />创建后设为活动</label></div><template v-if="profileKind === DataSourceType.POSTGRES"><div class="resource-form-grid resource-form-grid--4"><label>Host<input v-model="profileForm.host" /></label><label>Port<input v-model.number="profileForm.port" type="number" /></label><label>User<input v-model="profileForm.user" /></label><label>Password<input v-model="profileForm.password" type="password" /></label><label>Database<input v-model="profileForm.database" /></label><label>SSL Mode<input v-model="profileForm.sslMode" /></label><label>容器名<input v-model="profileForm.containerName" /></label></div></template><template v-else-if="profileKind === DataSourceType.REDIS"><div class="resource-form-grid"><label>地址<input v-model="profileForm.addr" /></label><label>用户名<input v-model="profileForm.username" /></label><label>密码<input v-model="profileForm.password" type="password" /></label><label>DB<input v-model.number="profileForm.db" type="number" /></label><label>容器名<input v-model="profileForm.containerName" /></label></div></template><template v-else><div class="resource-form-grid resource-form-grid--4"><label class="resource-check"><input v-model="profileForm.enabled" type="checkbox" />启用</label><label>Endpoint<input v-model="profileForm.endpoint" /></label><label>Region<input v-model="profileForm.region" /></label><label>Bucket<input v-model="profileForm.bucket" /></label><label>Access Key ID<input v-model="profileForm.accessKeyId" /></label><label>Secret Access Key<input v-model="profileForm.secretAccessKey" type="password" /></label><label>Prefix<input v-model="profileForm.prefix" /></label><label class="resource-check"><input v-model="profileForm.forcePathStyle" type="checkbox" />Force path style</label><label class="resource-check"><input v-model="profileForm.useSSL" type="checkbox" />使用 SSL</label></div><button type="button" class="resource-button resource-button--secondary" :disabled="working" @click="testProfileS3">测试 S3</button></template></form><template #footer><button class="button button--secondary" @click="profileOpen = false">取消</button><button type="submit" form="profile-form" class="button button--primary" :disabled="working">保存 Profile</button></template></SurfaceDialog>
    <SurfaceDialog :show="createJobOpen" title="创建 Agent 备份任务" description="幂等键由前端为本次提交自动生成，防止重复点击创建重复任务。" :width="DialogWidth.STANDARD" @close="createJobOpen = false"><form id="job-form" class="resource-form-stack" @submit.prevent="createJob"><label>备份类型<select v-model="jobForm.backupType"><option :value="BackupType.POSTGRES">Postgres</option><option :value="BackupType.REDIS">Redis</option><option :value="BackupType.FULL">完整备份</option></select></label><label class="resource-check"><input v-model="jobForm.uploadToS3" type="checkbox" />上传到 S3</label><label>Postgres Profile<select v-model="jobForm.postgresProfileId"><option value="">使用活动 Profile</option><option v-for="item in postgresProfiles" :key="item.profile_id" :value="item.profile_id">{{ item.name }}</option></select></label><label>Redis Profile<select v-model="jobForm.redisProfileId"><option value="">使用活动 Profile</option><option v-for="item in redisProfiles" :key="item.profile_id" :value="item.profile_id">{{ item.name }}</option></select></label><label v-if="jobForm.uploadToS3">S3 Profile<select v-model="jobForm.s3ProfileId"><option value="">使用活动 Profile</option><option v-for="item in s3Profiles" :key="item.profile_id" :value="item.profile_id">{{ item.name }}</option></select></label></form><template #footer><button class="button button--secondary" @click="createJobOpen = false">取消</button><button type="submit" form="job-form" class="button button--primary" :disabled="working">创建任务</button></template></SurfaceDialog>
    <SurfaceDialog :show="jobDetailOpen" title="Agent 备份任务详情" description="状态、错误、产物校验和 S3 对象信息。" :width="DialogWidth.WIDE" @close="jobDetailOpen = false"><pre v-if="jobDetail" class="resource-code">{{ JSON.stringify(jobDetail, null, 2) }}</pre></SurfaceDialog>
  </ConsoleShell>
</template>

